import java.util.*;
class Main {
  public static void main(String[] args) {
    List<Integer> xs = new ArrayList<>(List.of(1, 2, 3, 4));
    int sum = xs.stream().mapToInt(x -> x).sum();
    System.out.println(sum);
  }
}

